css:
.card {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  font-size: 20px;
  text-align: center;
  padding: 20px;
  line-height: 1.6;
}
.cloze {
  font-weight: bold;
  color: #3b82f6;
}
.sentence-meaning {
  font-size: 16px;
  color: #9aa0a6;
  margin-top: 14px;
}
.meaning {
  font-size: 15px;
  color: #80868b;
  margin-top: 8px;
}
.word-title {
  font-size: 24px;
  font-weight: bold;
  margin-top: 15px;
}
hr {
  border: 0;
  height: 1px;
  background-color: #555;
  margin: 18px 0;
}
.similar {
  font-size: 15px;
  color: #80868b;
  margin-top: 12px;
  text-align: left;
  display: inline-block;
  max-width: 520px;
}
.similar b {
  color: #3b82f6;
}

cardTemplates.Back:
{{cloze:Sentence}}
<div class="sentence-meaning">{{SentenceMeaning}}</div>
<br>
{{type:cloze:Sentence}}
<hr>
<div class="word-title">{{Word}}</div>
<div class="meaning">{{WordMeaning}}</div>
{{#SimilarWord}}<div class="similar">🔁 {{SimilarWord}}</div>{{/SimilarWord}}
{{tts en_US speed=1.2:Word}}
{{tts en_US speed=1.2:cloze:Sentence}}
